import os
candidates=[]
for base in ['/usr/bin','/opt/google/chrome','/usr/lib','/usr/local/bin']:
    if os.path.isdir(base):
        for root,dirs,files in os.walk(base):
            for f in files:
                if f in ('chrome','google-chrome','google-chrome-stable','chromium','chromium-browser'):
                    candidates.append(os.path.join(root,f))
            # prune deep
            if root.count(os.sep)-base.count(os.sep) > 4:
                dirs[:] = []
print('\n'.join(sorted(set(candidates))[:200]))
PY

